<?php declare(strict_types=1);require_once __DIR__.'/../lib/app_layout.php';require_once __DIR__.'/../lib/module_helpers.php';$user=require_role(['admin','principal','clerk']);$sid=(int)$user['school_id'];$pdo=db();$date=posted_date('date');if($_SERVER['REQUEST_METHOD']==='POST'&&valid_csrf($_POST['csrf']??null)){$p=$pdo->prepare('REPLACE INTO staff_attendance(school_id,user_id,date,status) VALUES(?,?,?,?)');$p->execute([$sid,(int)$_POST['user_id'],$date,$_POST['status']??'P']);flash_set('success','कर्मचारी उपस्थिती जतन झाली.');}$u=$pdo->prepare('SELECT u.*,COALESCE(a.status,"P") status FROM users u LEFT JOIN staff_attendance a ON a.user_id=u.id AND a.school_id=u.school_id AND a.date=? WHERE u.school_id=? ORDER BY u.name');$u->execute([$date,$sid]);$users=$u->fetchAll();layout_start('कर्मचारी उपस्थिती','attendance');?><form method="post" class="bg-white border rounded-2xl p-6"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="date" name="date" value="<?=e($date)?>" class="mb-5"><?php foreach($users as $row):?><div class="flex flex-wrap items-center justify-between gap-3 border-b py-3"><span><?=e($row['name'])?> <small class="text-slate-500">(<?=e($row['role'])?>)</small></span><input type="hidden" name="user_id" value="<?=$row['id']?>"><select name="status"><option value="P">उपस्थित</option><option value="A">अनुपस्थित</option></select><button class="text-teal font-bold">जतन</button></div><?php endforeach;?></form><?php layout_end();?>
